INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('OLA7_CT_2023_01:CODIGO_TRABAJO:549','mayalex_normativos','05_LABORAL','La Secretaría de Trabajo y Seguridad Social, se encargará de fomentar el desarrollo del movimiento sindical en forma armónica y ordenada, por todos los medios legales que juzgue convenientes. Al efecto, dictará por medio de decretos ejecutivos todas las disposiciones que sean necesarias, en los casos concurrentes, para garantizar la efectividad del derecho de sindicalización.','549','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":551,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"819e65eb94b6c85de12cec9da9f4e05f259345275cbc7c9f39866d5ca1750ec9","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:549","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','549','819e65eb94b6c85de12cec9da9f4e05f259345275cbc7c9f39866d5ca1750ec9','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:550','mayalex_normativos','05_LABORAL','Se entiende por huelga la suspensión colectiva, temporal y pacífica del trabajo, efectuad por los trabajadores de un establecimiento o empresa con fines económicos y profesionales propuestos a sus patronos y previos los trámites establecidos en el presente Título. Los Tribunales comunes deben sancionar de conformidad con la ley todo acto de coacción o de violencia que se ejecute con ocasión de una huelga, contra personas o propiedades.','550','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":552,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"4f449c77d62be181fbcda9cae53974e97421b544ebc83bd1510d88e1adb99154","ubicacion":["TÍTULO VII","CONFLICTOS COLECTIVOS DE TRABAJO","CAPÍTULO I","DISPOSICIONES GENRALES","DEFINICIÓN DE HUELGA"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:550","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','550','4f449c77d62be181fbcda9cae53974e97421b544ebc83bd1510d88e1adb99154','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:551','mayalex_normativos','05_LABORAL','La huelga deberá de tener por objeto:

1. Conseguir el equilibrio entre los diversos factores de la producción, armonizando los derechos del trabajo con los del capital;

2. Obtener del patrono la celebración o el cumplimiento del contrato y de las convenciones colectivas de trabajo; y,

3. Exigir la revisión en su caso del contrato y convenciones colectivas de trabajo, al terminar el período de su vigencia, en los términos y casos que este Código establece.','551','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":553,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"c8232f5f711714ceeb45b9493ba27b182a051e7eb8a1472abf548bfa091f450b","ubicacion":["OBJETO DE LA HUELGA"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:551","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','551','c8232f5f711714ceeb45b9493ba27b182a051e7eb8a1472abf548bfa091f450b','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:552','mayalex_normativos','05_LABORAL','La huelga legal suspende los contratos y convenciones de trabajo vigentes de la empresa, lugar o negocio en que se declare, por todo el tiempo que ella dure, sin terminar ni extinguir los derechos y las obligaciones que emanen de los mismos. El patrono no podrá celebrar nuevos contratos de trabajo durante el movimiento huelguístico, salvo en aquellas dependencias cuyo funcionamiento sea indispensable a juicio de la autoridad que conozca de la huelga, para evitar graves perjuicios a la seguridad y conservación de los talleres, locales, equipos, maquinarias o elementos básicos, solamente en el caso de que los huelguistas no autoricen el trabajo del personal necesario de esas dependencias.','552','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":554,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"e82858adc553c6beaf5bf7edfc5ae59cbebed98fe9b79f4c5d4aa986360dae77","ubicacion":["EFECTOS JURÍDICOS DE LAS HUELGAS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:552","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','552','e82858adc553c6beaf5bf7edfc5ae59cbebed98fe9b79f4c5d4aa986360dae77','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:553','mayalex_normativos','05_LABORAL','Para declarar una huelga se requiere:

a) Que tenga por objeto exclusivo algunos o algunos de los que señale el artículo 551 de este Código.

b) Agotar los procedimientos de arreglo directo, mediación, conciliación y arbitraje;

c) Que la declaren por lo menos las dos terceras partes de las personas que trabajen en la empresa, lugar o negocio de que se trate; y, d) Cumplir los demás requisitos establecidos en este Código.','553','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":555,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"7b7f7b51644ed94f4811af881d5dcf88664a46d6c223581f287a88a988056283","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:553","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','553','7b7f7b51644ed94f4811af881d5dcf88664a46d6c223581f287a88a988056283','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:554','mayalex_normativos','05_LABORAL','Se considera como servicio público toda actividad organizada que tienda a satisfacer necesidades de interés general en forma regular y continua, de acuerdo con un régimen jurídico especial, bien se realice por el Estado, directa o indirectamente, o por personas privadas.

Constituyen, por tanto, servicios público, entre otras, las siguientes actividades:

1. Las que presten en cualquiera de las ramas del Poder Público;
2. Las de empresas de transporte por tierra, agua y aire; y de acueducto, energía eléctrica y telecomunicaciones;
3. Las de establecimientos sanitarias de toda clase, tales como hospitales y clínicas;
4. Las de establecimientos de asistencia social, de caridad y de beneficencia;
5. Las de producción y suministro de alimentosa cuando se refieran a artículos de primera necesidad, siempre que se afecte alguna rama completa de este servicio;
6. Las de todos los servicios de la higiene y aseo de las poblaciones;
7. Las de explotación, refinación, transporte, y distribución de petróleo y de sus derivados, cuando estén destinadas al abastecimiento normal de combustible del país, a juicio del Gobierno:
8. Cualesquiera otras que a juicio del Gobierno interesen a la seguridad, sanidad, enseñanza y a la vida económica o social del pueblo, cuando hubieren sido restringidos las garantías individuales a que se refiere el artículo 163 de la Constitución de la República.
9. La decisión a que se refiere el párrafo anterior deberá tomarla el Presidente de la República mediante acuerdo dictado en Consejos de Ministros; y,
10. Las que tienen por objeto la investigación científica de enfermedades y operaciones de saneamiento vegetal y animal.','554','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":556,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"55c9d9fe7b67d757a74828c30213c01930c4405f9d6dac0a318958c2a1cdfe41","ubicacion":["SERVICIOS PÚBLICOS"],"constancias":[{"nota":42,"tipo":"REFORMA","texto":"Artículo 554. Numeral 8. Reforma tácita. El Código del Trabajo hace referencia a la Constitución de la República de 1957, Artículo 163. La Constitución de la República de 1982 se refiere, De los derechos Individuales en el Título III, Capítulo II.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:554","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','554','55c9d9fe7b67d757a74828c30213c01930c4405f9d6dac0a318958c2a1cdfe41','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:555','mayalex_normativos','05_LABORAL','En los servicios públicos a que se refiere el artículo anterior, el ejercicio del derecho de huelga estará sujeto a las siguientes restricciones:

En los casos de los incisos 1º, 7º, y 8º, las diferencias que ocurran entre patronos y trabajadores deben someterse antes de recurrir a la huelga, a conocimiento y resolución de la Secretaria de Trabajo y Seguridad Social a instancia de cualquiera de las partes.

Es ilegal una huelga en los servicios a que se refiere el inciso 2º mientras los trabajadores de una empresa de transporte no hayan terminado el viaje.

Es ilegal la huelga en las empresas indicadas en los incisos 3º, 4º, 5º, y 6º los mismos que de acuerdo, energía eléctrica y telecomunicaciones, si los trabajadores no proporcionaren el personal necesario para evitar que lasuspensión del servicio cauce un daño grave inmediato a la salud, a la seguridad oal economía públicas.

Es también ilegal la huelga, en caso de guerra, cuando los trabajadores pertenezcan a cualquier servicio público.','555','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":557,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"d8afdf5b5e7503639f584a4950c5464494fb63a2d7fae7b5e96c0f661a3d0d0f","ubicacion":["RESTRICCIONES AL DERECHO DE HUELGA","EN LOS SERVICIOS PÚBLICOS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:555","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','555','d8afdf5b5e7503639f584a4950c5464494fb63a2d7fae7b5e96c0f661a3d0d0f','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:556','mayalex_normativos','05_LABORAL','En cualquier caso en se representare de hecho la suspensión de los servicios a que se refiere el artículo anterior, el Poder Ejecutivo queda autorizado para asumir la dirección y administración por el tiempo indispensable para evitar perjuicios a la comunidad y tomará todas las providencias necesarias para restablecer los servicios suspendidos y garantizar su mantenimiento, previo decreto especial que indique los fundamentos de la medida.','556','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":558,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"1291401194a3c2f11e794d83b1a333cf11abb7be2dd8f133633b5face4dd89b2","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:556","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','556','1291401194a3c2f11e794d83b1a333cf11abb7be2dd8f133633b5face4dd89b2','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:557','mayalex_normativos','05_LABORAL','Los trabajadores del Estado o de sus instituciones o de las municipalidades, podrán ejercer el derecho de huelga sin sujeción a las restricciones establecidas en el Artículo 555, siempre que ocurra alguno de los dos siguientes casos:

a) Cuando se trate de vulnerar en cualquier forma el principio de alternabilidad en el ejercicio de la Presidencia de la República; y, b) Cuando se dé un golpe de Estado contra el Gobierno legalmente constituido.','557','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":559,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"85b96c00dfd594f79ed108f6fe56705d97b9827bc062269d64814837c1b9f2aa","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:557","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','557','85b96c00dfd594f79ed108f6fe56705d97b9827bc062269d64814837c1b9f2aa','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:558','mayalex_normativos','05_LABORAL','Las empresas de servicios públicos que no dependan directa e indirectamente del Estado no pueden suspender ni paralizar labores sino mediante permiso del Gobierno o dándole aviso a éste, con seis (6) meses de anticipación cuando menos, a fin de que puedan tomarse oportunamente las providencias que aseguren la continuidad del servicio.','558','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":560,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"8c7433d725355807e320439d4f04b6d209e01746c38bb01f13d3f743ab71741b","ubicacion":["EMPRESAS DE SERVICIOS PÚBLICOS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:558","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','558','8c7433d725355807e320439d4f04b6d209e01746c38bb01f13d3f743ab71741b','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:559','mayalex_normativos','05_LABORAL','Las empresas que no sean de servicio público no pueden clausurar sus labores mediante aviso a los trabajadores con no menos de un (1) mes de antelación, salvo fuerza mayor o caso fortuito, y sin perjuicio de las indemnizaciones a que haya lugar por razón de contratos de trabajo concertados por un tiempo mayor. Si la empresa clausurada reanudare actividades dentro de los ciento veinte (120) días siguientes, deberá admitir de preferencia al personal licenciado, en condiciones no inferiores a las que disfrutaba en el momento de la clausura. Los trabajadores, que debidamente avisados, no se presentaren dentro del tercer día, perderá este derecho preferencial.','559','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":561,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"0a442b6ac7fa87d9f7488e44482638275e97c911f5254ab080eb7582f466904f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:559","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','559','0a442b6ac7fa87d9f7488e44482638275e97c911f5254ab080eb7582f466904f','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:560','mayalex_normativos','05_LABORAL','Si los Tribunales de Trabajo declaran que los motivos de una huelga legal son imputables al patrono, por incumplimiento del contrato o contratos de trabajo, por negativa injustificada a celebrar un contrato o convención colectiva o por maltrato o violencia contra los trabajadores, condenarán a aquel al pago de los salarios correspondientes a los días en éstos que hayan holgado.

Los trabajadores que hayan desempeñado sus labores para evitar que la suspensión del servicio perjudique a la salud, seguridad o economía públicas, tienen derecho a salario doble.','560','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":562,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"2069cad5582a209dbfd3ce87402f8c6637f29eab574d0c1c179f0624beab6b91","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:560","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','560','2069cad5582a209dbfd3ce87402f8c6637f29eab574d0c1c179f0624beab6b91','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:561','mayalex_normativos','05_LABORAL','La huelga ilegal termina, sin responsabilidad para el patrono, con los contratos de trabajo de los huelguistas quienes deben pagar aquél los daños y perjuicios que prudencialmente determinen los Tribunales de Trabajo. Quedan a salvo las sanciones penales que en contra de éstos lleguen a declarar los tribunales comunes por delitos o faltas cometidos durante la huelga.

Sin embargo, en los nuevos contratos que celebre el patrono, no pueden estipularse condiciones inferiores a las que, en cada caso, regían antes de declararse la huelga ilegal.','561','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":563,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"ce139d1a05c3ea73954c8a8f1748dcd76450a2193c81a1fb6a5ee042046d0589","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:561","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','561','ce139d1a05c3ea73954c8a8f1748dcd76450a2193c81a1fb6a5ee042046d0589','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:562','mayalex_normativos','05_LABORAL','Antes de declararse la huelga se deberán cumplir los siguientes requisitos:

1. Los trabajadores dirigirán al patronato un escrito en que formulen sus peticiones, anuncien el propósito de ir a la huelga y expresen concretamente el objeto de la última, citando la fracción del artículo 551 en que estuviere comprendido. El aviso darse por lo menos, con seis (6) días de anticipación a la fecha señalada para suspender el trabajo; pero el plazo no será menor de diez (10) días cuando se trate de servicios públicos. El plazo se contará desdeel momento en que el patrono haya sido notificado.

La notificación tendrá además, como consecuencia, la de constituir al patrono por todo el término del aviso, en depositario o interventor, según el caso, del centro de trabajo, empresa o negociación que hayan de resultar afectados por la huelga, con las atribuciones y responsabilidades inherentes a esos cargos; y,

2. El escrito de petición a que se refiere la fracción anterior será presentado a la Junta de Conciliación y Arbitraje, acompañándole de una copia de que el presidente de dicha Junta hará llegar al patrono bajo su más estrecha responsabilidad, el mismo día en que la reciba. El patrono o su representante, también por o conducto de la Junta de Conciliación y Arbitraje, dentro de las cuarenta y ocho (48) horas siguientes, contestarán por escrito a las peticiones de los obreros.

Cuando el centro de trabajo, empresa o negociación no estén ubicados en el lugar en que dicha Junta radique, podrán los obreros entregar su escrito de peticiones a la autoridad del trabajo más próxima; y si no la hubiere, a la autoridad política de mayor jerarquía en el respectivo lugar. La autoridad que en cualquiera de los (2) casos anteriores reciba el pliego de peticiones, bajo su más estricta responsabilidad, el mismo día lo hará llegar al patrono; y después de dar vista a contestarse en el término de cuarenta y ocho (48) horas por la vía más rápida remitirá el expediente a la Junta de Conciliación y Arbitraje.','562','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":564,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"ab409405c0dcb0e412370fd95c6f75d0e926d02f5ad2ccda889cdd1a41bbe153","ubicacion":["CAPÍTULO II","DECLARATORIA Y DESARROLLO DE LA HUELGA"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:562","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','562','ab409405c0dcb0e412370fd95c6f75d0e926d02f5ad2ccda889cdd1a41bbe153','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:563','mayalex_normativos','05_LABORAL','La declaración de la huelga requiere que sea aprobada en votación secretas por las dos terceras partes de los trabajadores de la empresa o establecimiento o de la Asamblea General del sindicato de empresa o base a que estén afiliados más de la mitad de aquellos trabajadores.','563','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":565,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"0835c3b3fba5b95b99b8ba55f0307ca4d131668851e6f43143e393c94390fe31","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:563","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','563','0835c3b3fba5b95b99b8ba55f0307ca4d131668851e6f43143e393c94390fe31','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:564','mayalex_normativos','05_LABORAL','Una vez declarada la huelga, los trabajadores deben abandonar el lugar de trabajo.','564','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":566,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"51fb8db65b65b522da6d315e1abb20b66ef765562833d62dc3f44d2eb55299e8","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:564","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','564','51fb8db65b65b522da6d315e1abb20b66ef765562833d62dc3f44d2eb55299e8','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:565','mayalex_normativos','05_LABORAL','Cumplidos los procedimientos previos de arreglo directo, mediación, conciliación, y arbitraje, si el sindicato o grupo de trabajadores no sindicalizados declare la huelga, esta debe de efectuarse en forma ordenada y pacífica.','565','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":567,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"7b3442cb527866806ab30607033397e3544b086a4873fc36eea883c7b5915e8a","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:565","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','565','7b3442cb527866806ab30607033397e3544b086a4873fc36eea883c7b5915e8a','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:566','mayalex_normativos','05_LABORAL','Los directores del movimiento pueden constituir “Comités de Huelga” que sirvan de agentes de información de los trabajadores y de comunicación con los patronos o sus representantes.','566','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":568,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"bbed6c0a8f3cdbd23a022492dbe8c7019e845ab4958c46715756d7723777af92","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:566","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','566','bbed6c0a8f3cdbd23a022492dbe8c7019e845ab4958c46715756d7723777af92','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:567','mayalex_normativos','05_LABORAL','Cuando una huelga se prolongue por más de ocho (8) días, la Secretaría de Trabajo y Seguridad Social promoverá la constitución de un Tribunal de tres (3) miembros, designados, uno por los patronos, otro por los trabajadores y el tercero por la Secretaría; éste Tribunal estudiará el conflicto y propondrá a las partes una fórmula de arreglo, cuya adopción o rechazo por los trabajadores se votará en la forma prevista en el Artículo 563, y el mismo procedimiento se repetirá con intervalos de ocho (8) días. En cualquier caso, de morosidad o renuncia de las partes para la designación del miembro que les corresponda en los Tribunales a que este artículo se refiere, o para reemplazarlo cuando falte, la Secretaría procederá a hacer la designación respectiva.','567','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":569,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"febdbbbefc8d00725069d7600d360e6c606df62bda59f91bf471bb4864cc350c","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:567","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','567','febdbbbefc8d00725069d7600d360e6c606df62bda59f91bf471bb4864cc350c','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:568','mayalex_normativos','05_LABORAL','Los huelguistas, por medio de sus representantes, estarán obligados a mantener y el patrono o sus representantes obligados a aceptar, el número de trabajadores indispensables a juicio del respectivo Inspector de Trabajo, para que sigan ejecutándose las labores cuya suspensión perjudique gravemente la reanudación de los trabajos o la seguridad y conservación de los talleres o negociaciones. En caso necesario, la Dirección General del Trabajo podrá solicitar el auxilio de la fuerza pública, a fin de que otros trabajadores presten estos servicios y los huelguistas se niegan a hacerlo.','568','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":570,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"a03841f1780f40e2b0205691206e28ee4b3a80405404a961bf11bdf088782567","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:568","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','568','a03841f1780f40e2b0205691206e28ee4b3a80405404a961bf11bdf088782567','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:569','mayalex_normativos','05_LABORAL','La suspensión colectiva del trabajo es ilegal en cualquiera de los siguientes casos:

Cuando se trate de un servicio público; mientras no se hayan cumplido los requisitos establecidos en el artículo 555; Cuando persiga fines distintos de los profesionales o económicos; Cuando no se hayan cumplido previamente los procedimientos de arreglo directo, mediación, conciliación y arbitraje en forma legal; Cuando haya sido declarada con violación delo dispuesto en el artículo 563; Cuando se declare después de dos (2) meses de terminada la etapa de conciliación; Cuando no se limite a la suspensión pacífica del trabajo; y, Cuando se promueva con el propósito de exigir a las autoridades la ejecución de algún acto reservado a la determinación de ellas.','569','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":571,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"cbfcc9414e405f91ff91d1b589a5d441b82dc9acd8b8800d3e617a28acdd1ea9","ubicacion":["CAPÍTULO III","SUSPENSIÓN COLECTIVA ILEGAL DEL TRABAJO","CASO DE ILEGALIDAD Y SANCIONES."],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:569","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','569','cbfcc9414e405f91ff91d1b589a5d441b82dc9acd8b8800d3e617a28acdd1ea9','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:570','mayalex_normativos','05_LABORAL','La ilegalidad de una suspensión colectiva del trabajo será declarada administrativamente por el Ministerio del Trabajo y Previsión Social. La providencia respectiva deberá cumplirse inmediatamente, y contra ella sólo procederán las acciones pertinentes ante los Tribunales del Trabajo.

La reanudación de actividades no será óbice para que la Secretaría haga la declaratoria de ilegalidad correspondiente.

En la calificación de suspensiones colectivas de trabajo por las causales terceras y cualquiera del artículo 569 no se toman en cuenta las irregularidades adjetivas de trámite en que se haya podido incurrir.','570','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":572,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"fa0e05e2ccce133cb9d38df9877ed35ccbb785eee51e62035edaa0ddd0821661","ubicacion":["DECLARATORIA DE ILEGALIDAD"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:570","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','570','fa0e05e2ccce133cb9d38df9877ed35ccbb785eee51e62035edaa0ddd0821661','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:571','mayalex_normativos','05_LABORAL','Declarada la ilegalidad de una suspensión del trabajo, el patrono queda en libertad de despedir por tal motivo a quienes hubieren intervenido o participado en ella. A solicitud de parte interesada el Juez competente con vista a la resolución de la Secretaría de Trabajo y Seguridad Social, suspenderá por un término de dos (2) a seis (6) meses la personalidad jurídica del sindicato que haya promovido o apoyado la suspensión o paro del trabajo, y aun podrá decretarse su disolución, habida cuenta de la gravedad de los hechos. Las sanciones a que se refiere este artículo no excluyen la acción del patronato contra los responsables para la indemnización de los perjuicios que se le hayan causado.','571','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":573,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"08ccc6fd7798a82ab9be3fa501bb126e32652319b55c68bcbb54f6b431f777fd","ubicacion":[],"constancias":[{"nota":43,"tipo":"REFORMA","texto":"Artículo 571. Reformado por Decreto 760 de fecha 25 de mayo de 1979 y publicado en el Diario Oficial la Gaceta No. 22,811 del 28 de mayo de 1979.","decretos":["760"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:571","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','571','08ccc6fd7798a82ab9be3fa501bb126e32652319b55c68bcbb54f6b431f777fd','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:572','mayalex_normativos','05_LABORAL','La huelga terminará:

1. Por arreglos entre patronos y trabajadores;
2. Por laudo arbitral de la persona, comisión o tribunal que libremente elijan las partes; y,
3. Por Laudo de la Junta de Conciliación y Arbitraje respectiva.','572','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":574,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"56dcfbd00bea467e25694aa1c229a3458d8e64c1f76ad420b868148c1a818fe6","ubicacion":["CAPÍTULO IV","TERMINACIÓN DE LA HUELGA."],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:572","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','572','56dcfbd00bea467e25694aa1c229a3458d8e64c1f76ad420b868148c1a818fe6','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:573','mayalex_normativos','05_LABORAL','Mientras una huelga no termine por alguno de los medios que establece el artículo anterior, ni el patrono ni sus representantes podrán celebrar nuevos contratos con los huelguistas o con cualquier otra clase de trabajadores, individual o colectivamente, para la prestación de las labores en suspenso, salvo los casos especiales determinados por este Código.','573','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":575,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"3b8dcbc14940151003c891c0a9783f3e3f6fa5f81700c822c49c1c02759c6a70","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:573","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','573','3b8dcbc14940151003c891c0a9783f3e3f6fa5f81700c822c49c1c02759c6a70','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:574','mayalex_normativos','05_LABORAL','Paro legal es la suspensión temporal, parcial o total del trabajo ordenada por un (1) o más patronos, en forma pacífica y con el exclusivo propósito de defender sus intereses económicos y sociales.

Cuando se trate de personas jurídicas, el paro ha de ser ordenado por la junta directiva por los socios administradores.','574','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":576,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"bab3cdcd98aad3b100aa6ebd3a1db5a03132903ff31d01ecf64467a3e6c30529","ubicacion":["CAPÍTULO V","PAROS LEGALES E ILEGALES."],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:574","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','574','bab3cdcd98aad3b100aa6ebd3a1db5a03132903ff31d01ecf64467a3e6c30529','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:575','mayalex_normativos','05_LABORAL','El paro es legal cuando los patronos se ajustan a las disposiciones de los artículos 553 inciso b) y 574 y dan luego a todos sus trabajadores un aviso con un (1) mes de anticipación para el solo efecto de que estos puedan dar por terminados sus contratos, sin responsabilidad para las partes, durante ese período.

Este aviso se debe dar en el momento de concluirse los procedimientos de conciliación.','575','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":577,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"5e81edd287dd206be96c4e715672384e05d2002b88c3b634382f87470eec8cf9","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:575","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','575','5e81edd287dd206be96c4e715672384e05d2002b88c3b634382f87470eec8cf9','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:576','mayalex_normativos','05_LABORAL','Durante todo el tiempo que se mantenga en vigor el paro legal se entenderá suspendidos el contrato o contratos de los trabajadores que no hayan hecho uso de la facultad que les concede el artículo anterior. En ningún caso podrán estos reclamar el pago de salarios e indemnizaciones correspondiente al período de cesación del trabajo.','576','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":578,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"d3d33069c083fcbe1953bd728cb145b553ed15370fc85122189369ff9fb15a23","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:576","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','576','d3d33069c083fcbe1953bd728cb145b553ed15370fc85122189369ff9fb15a23','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:577','mayalex_normativos','05_LABORAL','La reanudación de los trabajos se hará de acuerdo con las normas que establece el artículo 103.','577','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":579,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"cbcd491be135299cf4c6ce1edac3be9d198de230549267c80eb23fc57af3344a","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:577","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','577','cbcd491be135299cf4c6ce1edac3be9d198de230549267c80eb23fc57af3344a','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:578','mayalex_normativos','05_LABORAL','Son aplicables al paro las disposiciones de los Artículos 550,párrafo segundo, 554, 555 y 556.','578','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":580,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"8ca58b58f940acba52ad3feec54e1c5e7ebfa1eb5c330b4f4c0df57e2dc77432","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:578","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','578','8ca58b58f940acba52ad3feec54e1c5e7ebfa1eb5c330b4f4c0df57e2dc77432','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:579','mayalex_normativos','05_LABORAL','Se tendrá por paro ilegal todo acto malicioso del patrono que imposibilite a los trabajadores el normal desempeño de sus labores.','579','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":581,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"8e50a7880c00d15951667ba0351f8d9bd1d87c208e0ef016d26c61585592dba3","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:579","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','579','8e50a7880c00d15951667ba0351f8d9bd1d87c208e0ef016d26c61585592dba3','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:580','mayalex_normativos','05_LABORAL','Todo paro ilegal tiene los siguientes efectos:

1- Faculta a los trabajadores para pedir su reinstalación inmediata o para dar por terminados sus contratos con derecho a percibir las prestaciones e indemnizaciones legales que procedan; 2- Hace incurrir al patronato en las obligaciones de reanudar sin perdida de tiempo los trabajos y de pagar a los trabajadores los salarios que debieron haber percibido durante el período en que estuvieron las labores indebidamente suspendidas; y, 3- Da lugar, en cada caso, a la imposición de una multa de cincuenta a un mil lempiras (L 50.00 a L 1.000.00), según la gravedad de la infracción y el número de trabajadores afectados por esta, sin perjuicio de las responsabilidades de cualquier otra índole que llegue a declarar contra sus autores la autoridad competente.','580','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":582,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"78d2eb8024132f028e26bcb9e695936ccbf43eeefc73f01d8694a047bbeab7ac","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:580","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','580','78d2eb8024132f028e26bcb9e695936ccbf43eeefc73f01d8694a047bbeab7ac','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:581','mayalex_normativos','05_LABORAL','Paro justo es aquel cuyos motivos son imputables a los trabajadores e injusto cuando son imputables al patrono.

Si los Tribunales de Trabajo y Seguridad Social declaran que los motivos de un paro legal son imputables al patrono, éste debe pagar a los trabajadores los salarios caídos a que se refiere el inciso 2º del artículo anterior.

En caso de paro legal declarado justo por dichos Tribunales procede el despido de los trabajadores sin responsabilidad para el patrono.','581','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":583,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"df5a919716cb00d3f9320f5a1edd419bf7572a80bfa685545b3e5d4f0772ba3f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:581","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','581','df5a919716cb00d3f9320f5a1edd419bf7572a80bfa685545b3e5d4f0772ba3f','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:582','mayalex_normativos','05_LABORAL','El paro decretado de acuerdo con lo que establece éste Capítulo, cesará cuando la Junta de Conciliación y Arbitraje que corresponda, después de oír a los interesados resuelva, que ya no existen las causas que lo determinaron.','582','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":584,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"673a2a9aff660007fd67e9860d4c95053d83f4bbb59b77cea6f17f6a6b270a23","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:582","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','582','673a2a9aff660007fd67e9860d4c95053d83f4bbb59b77cea6f17f6a6b270a23','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:583','mayalex_normativos','05_LABORAL','Al reanudarse los trabajos parcial o totalmente, estará obligado el patrono a admitir a los mismos trabajadores que prestaban sus servicios en la empresa cuando el paro fue decretado.

En este caso, la Secretaría de Trabajo y el patrono seguirán el procedimiento establecido en los párrafos segundo y tercero del Artículo 103 de este Código.','583','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":585,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"77c95703836308f30b302b2fa95f9b48c1090158907dc0f7fb76e63b693e461b","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:583","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','583','77c95703836308f30b302b2fa95f9b48c1090158907dc0f7fb76e63b693e461b','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:584','mayalex_normativos','05_LABORAL','Todo paro que se decrete fuera de los casos y sin los requisitos de los artículos anteriores, por medio de falsedades o por la creación ex profeso de las circunstancias que en esos artículos se mencionan, hará responsables a los patronos o a sus legítimos representantes que lo hayan decretado, a quienes se aplicarán las sanciones que este Código y el penal imponen a dichos actos u omisiones.','584','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":586,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"23c174567f63bc61c82dbc30d479f9ae423ec6f655424475424de546d3c8d2af","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:584","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','584','23c174567f63bc61c82dbc30d479f9ae423ec6f655424475424de546d3c8d2af','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:585','mayalex_normativos','05_LABORAL','Ni los paros ni las huelgas pueden perjudicar en forma alguna a los trabajadores que estuvieren percibiendo salarios o indemnizaciones por accidentes, enfermedades, maternidad, vacaciones u otras causas análogas.','585','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":587,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"2520024a714ec40b411210caf8193a98b080eadbd0d93cfad5f8f40315686b94","ubicacion":["CAPÍTULO VI","DISPOSICIONES COMUNES A LA HUELGA Y AL PARO"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:585","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','585','2520024a714ec40b411210caf8193a98b080eadbd0d93cfad5f8f40315686b94','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:586','mayalex_normativos','05_LABORAL','El hecho de que un paro o una huelga terminen por arreglo directo entre patronos y trabajadores o por decisión judicial, no exime de responsabilidad a los que hubieren cometido delitos o faltas con motivo del conflicto.','586','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":588,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"68571b57fbaea02054d804ca537767715ce7bf664365020bb7ed33554c8d1049","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:586","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','586','68571b57fbaea02054d804ca537767715ce7bf664365020bb7ed33554c8d1049','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:587','mayalex_normativos','05_LABORAL','En caso de huelga o para legalmente declarados, los Tribunales de Trabajo darán orden inmediata a las autoridades de policía para que protejan debidamente a las personas y propiedades y mantenga clausurados los establecimientos o negocios que el conflicto afecte, salvo en aquellas dependencias cuyo funcionamiento sea indispensable a juicio de la autoridad de trabajo.

En caso de huelga o paro ilegales los Tribunales de trabajo ordenarán las autoridades de policía que garanticen por todos los medios a su alcance la continuación de los trabajos, y si se tratare de servicios públicos en manos de empresas particulares el Poder Ejecutivo podrá sumir su dirección y administración en los términos del artículo 556.','587','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":589,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"2a9f430b6030618a22c4688439293d41dfafd3199ac12f0f3ec1398033ccd47f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:587","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','587','2a9f430b6030618a22c4688439293d41dfafd3199ac12f0f3ec1398033ccd47f','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:588','mayalex_normativos','05_LABORAL','El derecho de los patronos al paro y de los trabajadores a la huelga son irrenunciables, pero será válida la cláusula en virtud de la cual se comprometan a no ejercer los temporalmente, mientras una de las partes no deje de cumplir los términos del convenio colectivo de trabajo suscrito entre el patrono de que se trate y las dos terceras (2/3) partes de sus trabajadores.

Igualmente, los tribunales de Trabajo pueden suspender el ejercicio de estos derechos por un tiempo no mayor de seis (6) meses, siempre que al resolver determinado conflicto grave de carácter económico y social lo consideren indispensable para obtener mayor equilibrio en las relaciones de patronos y trabajadores.','588','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":590,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"37ad646f5494e175e4d56fcbc906e120b85702e0950df35f63bda18a7c501264","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:588","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','588','37ad646f5494e175e4d56fcbc906e120b85702e0950df35f63bda18a7c501264','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:589','mayalex_normativos','05_LABORAL','Toda persona que incite públicamente a que una huelga o paro se efectúe contra las disposiciones de este Título será sancionada con multas de cien a quinientos lempiras (L 100.00 a L 500.00).','589','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":591,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"f79929705572f01ec86927071f13bb4a075c7968f9ed48151cb04cc807801d95","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:589","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','589','f79929705572f01ec86927071f13bb4a075c7968f9ed48151cb04cc807801d95','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:590','mayalex_normativos','05_LABORAL','Los individuos que con ocasión de un conflicto colectivo participaren en éste para promover el desorden o quitarle su carácter pacífico, serán detenidos y arrestados por cualquier autoridad hasta que termine la huelgao paro, o hasta que rindieren fianza de no ejecutar lo proyectado, a satisfacción delos Tribunales de Trabajo.','590','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":592,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"256959e470daea05525dd83e0d063b85b808a89ea4047b0133929310f039c739","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:590","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','590','256959e470daea05525dd83e0d063b85b808a89ea4047b0133929310f039c739','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:591','mayalex_normativos','05_LABORAL','Corresponde a la Secretaría de Trabajo y Seguridad Social:

1. Autorizar, cumplir y hacer cumplir las leyes y reglamentos relativos al ramo;
2. Elaborar su Reglamento Interior;
3. La dirección, estudio y despacho de todos los asuntos relacionados con el trabajo y la previsión social;
4. El mejoramiento de las condiciones de vida y de trabajo de los obreros;
5. La Vigilancia e inspección respecto al debido cumplimiento de las disposiciones legales relativas a las relaciones obrero-patronales;
6. La revisión y aprobación de los reglamentos de trabajo que presenten a su consideración las empresas del Estado y las particulares;
7. Armonizar las relaciones entre patronos y trabajadores;
8. La fijación de salarios mínimos, sobre la base de los dictámenes que le presente la Comisión Nacional de Salario Mínimo.
9. Aprobar o improbar los estatutos de las organizaciones sociales;

10. El estudio y solución de los problemas relacionados con la desocupación.
11. La preparación de estadísticas de carácter laboral;
12. Proponer a la Corte Suprema de Justicia, para su nombramiento, candidatos para Jueces del Trabajo;
13. Coordinar su acción en materia de Seguridad Social, con el Instituto Hondureño de Seguridad Social (IHSS), sujetándose a lo que dispongan las leyes y reglamentos correspondientes;
14. El reconocimiento y registro de las asociaciones obreras y patronales;
15. La Procuraduría del Trabajo;
16. Contrato de trabajo de los extranjeros y los nacionales en el extranjero;
17. El fomento y vigilancia de Sociedades Cooperativas formadas por los trabajadores;
18. La investigación científica de los problemas de la clase trabajadora;
19. Congresos y reuniones nacionales internacionales de trabajo; y,
20. Los estudios e iniciativas relacionadas con el Código de Trabajo y sus reglamentos.','591','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":593,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"1279e5b3563468b98b825983c815731fe0dff3011f4c50f71d3ee12bb2c9b3a1","ubicacion":["TÍTULO VIII","ORGANIZACIÓN ADMINISTRATIVA DEL TRABAJO","CAPÍTULO I","SECRETARÍA DE TRABAJO Y PREVISIÓN SOCIAL"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:591","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','591','1279e5b3563468b98b825983c815731fe0dff3011f4c50f71d3ee12bb2c9b3a1','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:592','mayalex_normativos','05_LABORAL','Los asuntos a que se refiere el artículo anterior son de competencia exclusiva de las autoridades que este Código crea y cualesquiera otras autoridades quedan obligadas a prestarles la cooperación y auxilio que aquellas les demanden.','592','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":594,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"5996744363851249c3aa6996f8db3b7982ec956a521f03e12fdced82e1494ed3","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:592","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','592','5996744363851249c3aa6996f8db3b7982ec956a521f03e12fdced82e1494ed3','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:593','mayalex_normativos','05_LABORAL','La Secretaría de Trabajo y Seguridad Social tiene los siguientes departamentos:

a) La Dirección General del Trabajo;
b) La Inspección General del Trabajo;
c) Dirección General de Seguridad Social;
d) Procuraduría del Trabajo;
e) Instituto Nacional de Investigación y de Estudios Sociales; y,
f) Los demás que determine el reglamento de éste Capítulo o las leyes que posteriormente se dicten.','593','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":595,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"07c2e0b8e837b5ff57cf5f123cf51baf6d87baa1a0995c0f96d9bd27d6bb4855","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:593","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','593','07c2e0b8e837b5ff57cf5f123cf51baf6d87baa1a0995c0f96d9bd27d6bb4855','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:594','mayalex_normativos','05_LABORAL','La Dirección General del Trabajo tendrá funciones puramente administrativas, como registro de las organizaciones sociales, registro de los contratos y convenciones de trabajo que se celebren en el país, servicios de estadísticas y colocaciones y todas las demás que le atribuyen este Código y sus reglamentos.','594','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":596,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"c5cf595e0fc5886710499bd78ba9cf049acbc0dc371e0f18244d48bd2bc8be8b","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:594","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','594','c5cf595e0fc5886710499bd78ba9cf049acbc0dc371e0f18244d48bd2bc8be8b','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:595','mayalex_normativos','05_LABORAL','La Dirección General de Seguridad Social realizará una eficaz coordinación entre todas las instituciones de previsión y de asistencia sociales que existan o lleguen a existir en el país, a fin de propender a su constante progreso y mejoramiento.','595','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":597,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"9c1dcc6a3f9e56cadd3d0ce57fd646d2ae8cddf34338b967308a8c57491f80c0","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:595","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','595','9c1dcc6a3f9e56cadd3d0ce57fd646d2ae8cddf34338b967308a8c57491f80c0','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:596','mayalex_normativos','05_LABORAL','El Instituto Nacional de Investigación y de Estudios Sociales tendrá por misión realizar toda clase de encuestas y estudios sobre salarios, costos de vida y demás materias referentes a trabajo, asistencia y previsión social, para lo cual armonizará sus actividades con las de los otros departamentos y establecerá un constante intercambio con los demás países de América y del mundo en general, por medio de los organismos correspondientes, a fin de conocer sus problemas, instituciones y conquistas en el campo de la acción social.

Tendrá además las siguientes facultades:

a) Compilar datos sobre las condiciones de trabajo;
b) Estudiar, recibir y archivar los informes que los patronos deban enviar a la

Dirección General del Trabajo en virtud de leyes, reglamentos o decretos y hacer resúmenes de los mismos.
c) Recoger y mantener información actualizada de la ocupación y desocupación en todo el país de conformidad con las disposiciones especiales que seemitan;
d) Proponer a la Dirección General los formularios que sean necesarios para el cumplimiento de su cometido; y,
e) Las que se establecieren por disposiciones especiales.','596','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":598,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"cc610b74a8009777177d1e0af0dfa0fb8cb81268de207a076ebaa8bca91a23d7","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:596","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','596','cc610b74a8009777177d1e0af0dfa0fb8cb81268de207a076ebaa8bca91a23d7','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:597','mayalex_normativos','05_LABORAL','La Dirección General del Trabajo es el órgano o autoridad de aplicación de las leyes del trabajo en primera instancia en lo administrativo y tendrá los siguientes cometidos y funciones específicas:

a) Propender, por todos los medios adecuados, a que exista la mayor armonía entre patronos y trabajadores;

b) Impulsar la negociación y la contratación colectivas como medio de resolver las diferencias entre patronos y trabajadores; de mejorar las relaciones profesionales y las condiciones de trabajo en general, procurando el logro de salarios justos y equitativos y el cumplimiento de los deberes del trabajador en cuanto al tiempo y eficiencia en el trabajo;

c) Mantener estrechas relaciones con las organizaciones de patronos y de trabajadores y fomentar su colaboración en la aplicación y desarrollo de la legislación laboral;

d) Promover la constitución de los organismos mixtos, paritarios o de seguridad que sean obligatorios por disposición legal, reglamentaria, convencional, y de aquéllos que puedan contribuir al mejoramiento de las condiciones de trabajo y de las relaciones profesionales;

e) Asesorar al Secretario de Trabajo y Seguridad Social en las materias de su competencia;

f) Autorizar y registrar los documentos que se establecieren para el control de las leyes de trabajo y organizar el archivo de los mismos;

g) Cumplir funciones de conciliación en los conflictos o diferencias colectivas o individuales y tomar los acuerdos correspondientes sin perjuicio de la función de los órganos jurisdiccionales;

h) Proponer a la Secretaría de Trabajo y Seguridad Social los reglamentos o disposiciones que estime necesarios para mejorar la aplicación y cumplimiento de leyes reglamentos o convenios o ampliar el derecho positivo laboral;

i) Imponer las sanciones que establece este Código y formular prevenciones en los casos de infracciones menores.','597','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":599,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"80f0602b59132a3bf30c3332f94d7a2852caf47466bf29e508aa2985ea20775e","ubicacion":["CAPÍTULO II","DIRECCIÓN GENERAL DEL TRABAJO"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:597","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','597','80f0602b59132a3bf30c3332f94d7a2852caf47466bf29e508aa2985ea20775e','OLA7_CT_2023_01',now()),
('OLA7_CT_2023_01:CODIGO_TRABAJO:598','mayalex_normativos','05_LABORAL','La Dirección General del Trabajo estará a cargo de un Director General, quien será sustituido automáticamente por el Sub-Director General en los casos de ausencia, así como en los de excusa o recusación aceptadas por la Secretaría de Trabajo y Seguridad Social.

En cada zona económica habrá una o más oficinas regionales dependientes de la Dirección General de Trabajo, las cuales tendrán como funciones las establecidas en el artículo 597 letras a), b), c), d) y g) del referido Código.','598','Código del Trabajo de Honduras (Decreto No. 189 de 1959)','{"norm_id":"HN:CODIGO_TRABAJO","instrumento_id":"CODIGO_TRABAJO","ingest_batch":"OLA7_CT_2023_01","ola":"OLA7","ordinal":600,"decreto":"189-1959","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada del CEDIJ (Poder Judicial), «Codigo del Trabajo (mayo 2018).pdf», Word 2019, 23-oct-2023; notas al pie con la cita de cada decreto.","pdf_sha256":"75265ef93f52cbf3486ed00a7e9cec3a65a851d34162ac9e4a66720aee4d08bf","article_sha256":"929def3109327a782ab8f97c69465b512bd424e16c7d88d33cd72c0392d8987f","ubicacion":["EL DIRECTOR GENERAL"],"constancias":[{"nota":44,"tipo":"REFORMA","texto":"Artículo 598. Reformado por Adición del párrafo segundo según Decreto No.50 del 10 de marzo de 1965, publicado en el Diario Oficial La Gaceta No.18, 532 del 31 de marzo de 1965.","decretos":["50"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"v2trabajo:mayalex_normativos:598","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_TRABAJO','598','929def3109327a782ab8f97c69465b512bd424e16c7d88d33cd72c0392d8987f','OLA7_CT_2023_01',now())
